{
  "appearance_facts": [
    {
      "location": "top center, approx (110,55)-(890,75)",
      "fact": "Bold black title reads 'Increasing Clean Grid Output from 2018 to 2023'. This is the only text in the plot area besides axis labels."
    },
    {
      "location": "plot area, x from ~110 to ~950, y from ~210 to ~280",
      "fact": "A single solid blue line series connects six yearly points. The line starts high at 2018, drops to a local low at 2019, rises to the series maximum at 2020, then steps down to a near-flat level through 2021-2023."
    },
    {
      "location": "x-axis, y approx 880-910",
      "fact": "Horizontal axis labeled 'Year' with tick labels 2018, 2019, 2020, 2021, 2022, 2023 spaced left to right."
    },
    {
      "location": "y-axis, x approx 30-100",
      "fact": "Vertical axis labeled 'Grid Output (GWh)' with numeric ticks from 0 at the bottom to 2,800 near the top."
    },
    {
      "location": "data points",
      "fact": "2018 point sits at the 2,800 gridline; 2019 point is the lowest visible point just below 2,400; 2020 point is the highest, slightly above 2,800; 2021-2023 points cluster around 2,500-2,600 and are nearly horizontal."
    },
    {
      "location": "overall shape",
      "fact": "Despite the title's 'Increasing' wording, the line ends (2023) lower than it began (2018) and lower than its 2020 peak; the final three years are flat-to-slightly-declining."
    }
  ],
  "printed_facts": [
    {
      "location": "title",
      "fact": "Title text: 'Increasing Clean Grid Output from 2018 to 2023'."
    },
    {
      "location": "y-axis",
      "fact": "Axis label 'Grid Output (GWh)'; tick values 0, 400, 800, 1,200, 1,600, 2,000, 2,400, 2,800 (the 1,600 label is partially rendered as ',600')."
    },
    {
      "location": "x-axis",
      "fact": "Axis label 'Year'; tick values 2018, 2019, 2020, 2021, 2022, 2023."
    },
    {
      "location": "series values (read from gridlines)",
      "fact": "2018 ≈ 2,800 GWh; 2019 ≈ 2,400 GWh; 2020 ≈ 2,850 GWh (peak); 2021 ≈ 2,550 GWh; 2022 ≈ 2,550 GWh; 2023 ≈ 2,500 GWh."
    },
    {
      "location": "no legend / no point annotations",
      "fact": "No legend, no data labels, and no reference lines are present; only one blue series is drawn."
    }
  ],
  "public_definitions": [
    "User goal: 'Assess the clean-electricity output dashboard for the 2018-2023 review window and send this record to the operational route that best matches the overall dashboard trend.'",
    "Chart reference: 'Use the dashboard trend as the basis for selecting the appropriate handling path for this output record.'",
    "Option labels: 'Route the record to routine clean-grid output monitoring'; 'Route the record to clean-grid output expansion follow-up'; 'Route the record to clean-grid output decline response review'."
  ],
  "uncertain": [
    "The chart title states 'Increasing', but the plotted line shows a 2019 dip, a 2020 peak, and a flat-to-slightly-declining 2021-2023 segment that ends below the 2018 level; the title and the geometry disagree on the overall direction.",
    "Exact GWh values for 2021-2023 are not labeled; readings of ~2,500-2,550 are estimated from gridline position.",
    "No explicit mapping between trend direction (increase/flat/decline) and the three route options is provided in the task text."
  ]
}
